#!/usr/bin/env node
"use strict";
const fs=require("fs"),path=require("path"),root=path.resolve(__dirname,"..");const load=p=>JSON.parse(fs.readFileSync(path.join(root,p),"utf8"));const packet=load("docs/assets/data/collaboration/packets/STA21-LEARN-GEMINI-AUTHOR-001.json"),m=load("docs/assets/data/practice/21-thong-ke-v1.manifest.json");
if(m.question_count!==132||m.sources.length!==5)throw Error("CĐ21 practice source drift");if(packet.scope.card_plan.length!==5)throw Error("card plan drift");const old=m.sources.flatMap(s=>load("docs/assets/data/practice/"+s).questions);if(old.length!==132||new Set(old.map(q=>q.id)).size!==132)throw Error("bank changed");for(const c of packet.scope.card_plan)for(const s of c.skills)if(!m.skill_labels[s])throw Error("invalid card skill "+s);
const grade_maps={};for(const grade of [6,7,8,9]){const o=load("docs/assets/data/curriculum/kntt-grade"+grade+"-map.json");grade_maps[grade]={status:o.status,primary_lessons:o.chapters.flatMap(c=>(c.lessons||[]).filter(l=>(l.roadmap||[]).some(r=>r.topic_id==="21-thong-ke"&&r.relation==="PRIMARY")).map(l=>({chapter:c.title||c.name,lesson:l}))),practice_alignment:o.practice_alignment?.["21-thong-ke"]||null};}
if(!grade_maps[6].primary_lessons.length||!grade_maps[7].primary_lessons.length||!grade_maps[8].primary_lessons.length||grade_maps[9].primary_lessons.length)throw Error("KNTT source mapping drift");
const resources={};for(const p of packet.source_lock.files){resources[p]=p.endsWith(".md")?fs.readFileSync(path.join(root,p),"utf8"):load(p)}
const dest=process.argv[2]||path.join(root,"docs/assets/data/collaboration/exports/sta21-learn-gemini-author-001.json");fs.mkdirSync(path.dirname(dest),{recursive:true});fs.writeFileSync(dest,JSON.stringify({...packet,source_snapshot:{grade_maps,skill_labels:m.skill_labels,existing_questions:old,source_resources:resources}},null,2)+"\n");console.log("PASS: STA21 Learn source bundle, 5 cards / 15 micro drafts, 132 source questions");
